/// JSON object: key → string or plural forms.
pub const EN: &str = r#"{"dwg.version":"AutoCAD {v}","dxf2000.save.mleader":{"one":"{n} multileader was saved as the lines, arrowhead and text it draws (DXF 2000 has no multileaders; save as DWG to keep it).","other":"{n} multileaders were saved as the lines, arrowheads and text they draw (DXF 2000 has no multileaders; save as DWG to keep them)."},"model3d.faces_file":"Faces from the file","dwg.read.xrefs":{"one":"{n} linked drawing (external reference) is not loaded: XREF, Reload, then pick its file, to see it.","other":"{n} linked drawings (external references) are not loaded: XREF, Reload, then pick their files, to see them."},"dwg.save.xref.bound":{"one":"{n} linked drawing was bound into the file: other programs see ordinary blocks and layers named Name$0$….","other":"{n} linked drawings were bound into the file: other programs see ordinary blocks and layers named Name$0$…."},"dwg.save.xref.link":{"one":"{n} linked drawing CadCraft did not load is saved as a link to its file.","other":"{n} linked drawings CadCraft did not load are saved as links to their files."},"dwg.read.mleaderblocks":{"one":"{n} multileader (with a block, several leader lines or curved lines) is drawn as the other program drew it: it moves as one, but is not editable as a multileader.","other":"{n} multileaders (with a block, several leader lines or curved lines) are drawn as the other program drew them: they move as one, but are not editable as multileaders."},"dwg.read.wipeouts":{"one":"{n} wipeout is drawn as its frame: CadCraft does not hide what is under it yet.","other":"{n} wipeouts are drawn as their frames: CadCraft does not hide what is under them yet."},"dwg.read.images":{"one":"{n} picture is shown as a frame with its file name until you give CadCraft the file: type IMAGE and pick it (the drawing stores only where it was).","other":"{n} pictures are shown as frames with their file names until you give CadCraft the files: type IMAGE and pick them (the drawing stores only where they were)."},"dxf.save.lw":"Lineweights were left out: R12 has none (save as DWG to keep them).","dxf.save.tr":"R12 has no transparency: other programs show those objects solid (CadCraft keeps it; save as DWG for everyone).","dwg.save.material":"Materials are kept for CadCraft; other programs show the layer's material.","dwg.save.tr2000":"The 2000 format has no transparency: other programs show those objects solid (CadCraft keeps it; save as 2004 or later for everyone).","dwg.save.dyn.dropped":{"one":"{n} dynamic block was changed in CadCraft and is saved as a plain block.","other":"{n} dynamic blocks were changed in CadCraft and are saved as plain blocks."},"dwg.save.dyn.version":{"one":"{n} dynamic block keeps its parameters only in the version the drawing came in: in {v} it opens as a plain block.","other":"{n} dynamic blocks keep their parameters only in the version the drawing came in: in {v} they open as plain blocks."},"dxf.save.lts":{"one":"{n} object's own linetype scale was left out: R12 has only the drawing's (save as DWG to keep it).","other":"{n} objects' own linetype scales were left out: R12 has only the drawing's (save as DWG to keep them)."},"dxf.save.mleader":{"one":"{n} multileader was saved as the lines, arrowhead and text it draws (R12 has no multileaders).","other":"{n} multileaders were saved as the lines, arrowheads and text they draw (R12 has no multileaders)."},"dxf.save.paperview":{"one":"{n} named view of a sheet was saved as a paper-space view: R12 does not record which sheet, so CadCraft puts it on the first sheet when the file is opened again.","other":"{n} named views of sheets were saved as paper-space views: R12 does not record which sheet, so CadCraft puts them on the first sheet when the file is opened again."},"dwg.save.truecolor":"True colours were saved as the nearest standard colour (AutoCAD 2000 files have only the 255 standard ones; save as AutoCAD 2004 or later to keep them).","dwg.save.hatch.unknown":{"one":"{n} hatch with a pattern CadCraft does not know was saved with its boundary and pattern name only.","other":"{n} hatches with a pattern CadCraft does not know were saved with their boundary and pattern name only."},"dwg.save.mleader":{"one":"{n} multileader was saved as the lines, arrowhead and text it draws (DWG multileaders are not written yet).","other":"{n} multileaders were saved as the lines, arrowheads and text they draw (DWG multileaders are not written yet)."},"dwg.save.mtextwidth":"Multi-line text keeps its letters at normal width (a width factor applies only to single-line text in DWG).","dwg.save.paperview":{"one":"{n} named view of a sheet was saved as a paper-space view: DWG does not record which sheet, so CadCraft puts it on the first sheet when the file is opened again.","other":"{n} named views of sheets were saved as paper-space views: DWG does not record which sheet, so CadCraft puts them on the first sheet when the file is opened again."},"dwg.save.model3d":{"one":"The 3D model was saved: {n} face as 3DFACE on layer {layer}, so other programs see the solids, and CadCraft's exact copy in block {block}.","other":"The 3D model was saved: {n} faces as 3DFACE on layer {layer}, so other programs see the solids, and CadCraft's exact copy in block {block}."},"dwg.save.other":{"one":"{n} object of a kind DWG saving does not know yet was left out.","other":"{n} objects of a kind DWG saving does not know yet were left out."},"model3d.read.placed":"{n} faces from block references came into the 3D tab, placed as each reference places them.","model3d.read.flat":"{n} 3D faces inside blocks or on sheets are drawn flat in 2D, as closed outlines.","dxf.autocad_binary_dxf":"AutoCAD Binary DXF","dxf.binary_dxf_save_ascii":"This is a binary DXF. Save it as ASCII DXF (or open the DWG) and try again.","dxf.attdef_outside_block":"ATTDEF (outside a block)","dxf.dimension_parametric_constraint":"DIMENSION (parametric constraint)","dxf.hatch_boundary_ellipse_spline":"HATCH boundary (ellipse or spline edge)","dxf.solid_line":"Solid line","dxf.true_colours_were_saved":"True colours were saved as the nearest standard colour.","dxf.multi_line_text_was":"Multi-line text was saved as one text per line.","dwg-import.hatch_boundary_not_read":"HATCH (boundary not read)","dwg-import.dimension_parametric_constraint":"DIMENSION (parametric constraint)","dwg-import.dimension_no_block_draw":"DIMENSION (no block to draw it from)","dwg-import.acad_table_no_block":"ACAD_TABLE (no block to draw it from)","dxf.read.bad_group_code":"This file is not a readable DXF (bad group code on line {line}).","dxf.save.renamed":{"one":"{n} layer or block name was changed to fit R12 (31 characters of A–Z, 0–9, $ _ -).","other":"{n} layer or block names were changed to fit R12 (31 characters of A–Z, 0–9, $ _ -)."},"dxf.save.hatch":{"one":"{n} hatch was saved as its outline (R12 has no hatch).","other":"{n} hatches were saved as their outlines (R12 has no hatch)."},"dxf.save.ellipse":{"one":"{n} ellipse was saved as polylines.","other":"{n} ellipses were saved as polylines."},"dxf.save.longattr":{"one":"{n} attribute value was longer than R12 allows (255 characters) and was shortened.","other":"{n} attribute values were longer than R12 allows (255 characters) and were shortened."},"dxf.save.noplot":{"one":"R12 cannot mark a layer \"do not plot\": other programs will plot the layer {layers} (CadCraft remembers).","other":"R12 cannot mark a layer \"do not plot\": other programs will plot the layers {layers} (CadCraft remembers)."},"dxf.save.noplot_nolayout":{"one":"R12 cannot mark a layer \"do not plot\": other programs will plot the layer {layers} (CadCraft remembers only when the drawing has a layout).","other":"R12 cannot mark a layer \"do not plot\": other programs will plot the layers {layers} (CadCraft remembers only when the drawing has a layout)."},"dxf.save.layouts":{"one":"R12 holds one layout. \"{first}\" is the paper space every program shows; {layouts} is kept as block {blocks}, which CadCraft opens as layouts again.","other":"R12 holds one layout. \"{first}\" is the paper space every program shows; {layouts} are kept as blocks {blocks}, which CadCraft opens as layouts again."},"dxf.save.model3d":{"one":"The 3D model was saved: {n} face as 3DFACE on layer {layer}, so other programs see the solids, and CadCraft's exact copy in block {block}.","other":"The 3D model was saved: {n} faces as 3DFACE on layer {layer}, so other programs see the solids, and CadCraft's exact copy in block {block}."},"model3d.read.not_restored":"The 3D model CadCraft saved in this file could not be restored ({why}). Its faces were read instead, as loose faces.","model3d.read.loose_faces":{"one":"{n} 3D face came in on the 3D tab as a loose face (not a solid), kept as one group.","other":"{n} 3D faces came in on the 3D tab as loose faces (not solids), kept together as one group."},"model3d.read.faces_left_out":{"one":"{n} more 3D face was left out (200,000 at most).","other":"{n} more 3D faces were left out (200,000 at most)."},"dwg.read.splines":{"one":"{n} spline was converted to polylines.","other":"{n} splines were converted to polylines."},"dwg.read.dimblocks":{"one":"{n} dimension could only be read as drawn (from its block), not as an editable dimension.","other":"{n} dimensions could only be read as drawn (from their blocks), not as editable dimensions."},"dxf.save.pictures":{"one":"{n} picture is saved as its frame with the file name: DXF from CadCraft has no pictures yet (DWG keeps them).","other":"{n} pictures are saved as their frames with the file names: DXF from CadCraft has no pictures yet (DWG keeps them)."},"dxf.save.textmask":{"one":"{n} text has a background mask, which DXF R12 cannot hold: it is saved without it (DWG and DXF 2000 keep it).","other":"{n} texts have background masks, which DXF R12 cannot hold: they are saved without them (DWG and DXF 2000 keep them)."},"dwg.save.mask2000":{"one":"{n} text has a background mask, which the 2000 format cannot hold: save as 2004 or later to keep it.","other":"{n} texts have background masks, which the 2000 format cannot hold: save as 2004 or later to keep them."},"dxf.save.infinite":{"one":"{n} construction line (XLINE or RAY) is saved as a line across the drawing: DXF R12 has neither (DWG and DXF 2000 keep them).","other":"{n} construction lines (XLINE or RAY) are saved as lines across the drawing: DXF R12 has neither (DWG and DXF 2000 keep them)."},"dxf.save.vpovr":{"one":"{n} viewport shows some layers in its own colour, linetype, lineweight or transparency: DXF from CadCraft does not keep that yet (DWG does).","other":"{n} viewports show some layers in their own colours, linetypes, lineweights or transparency: DXF from CadCraft does not keep that yet (DWG does)."},"dwg.save.clipdyn":{"one":"{n} clipped reference is also a dynamic block: it is saved without its clip.","other":"{n} clipped references are also dynamic blocks: they are saved without their clips."},"dxf.save.xclip":{"one":"{n} clipped reference is saved whole: DXF R12 cannot clip (DWG and DXF 2000 keep the clip).","other":"{n} clipped references are saved whole: DXF R12 cannot clip (DWG and DXF 2000 keep the clips)."}}"#;
